class SelectDialogController{constructor($mdDialog,DispatchData,toastrService,id,fieldName,title,job,options,initialValue,showCheckbox,checkboxLabel){this._$mdDialog=$mdDialog;this._dispatchData=DispatchData;this.toastrService=toastrService;this.showCheckbox=!showCheckbox?false:showCheckbox;this.checkboxLabel=!checkboxLabel?"":checkboxLabel;this.isLoading=false;this.id=id;this.title=title;this._job=job;this._fieldName=fieldName;this.options=options;this.selectedOption=null;this.checkboxValue=false;if(initialValue){this.selectedOption=this._findInitialValue(options,initialValue)}}_findInitialValue(options,initialValue){return options.items.find(option=>option.text===initialValue)??null}async submit(selectedOption){try{this.isLoading=true;if(this._fieldName==="DGClass"){await this._updateDgClass(selectedOption)}else{this._job.bulkJob?await this._dispatchData.updateBulkJobDetail(this._job.id,this._fieldName,selectedOption.id,this._job.charge,FirstName,ContactID):await this._dispatchData.updateJobDetail(this._job.id,this._fieldName,selectedOption.id,this._job.charge,FirstName,ContactID)}this._$mdDialog.hide()}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.isLoading=false}}async _updateDgClass(selectedOption){await this._dispatchData.updateJobDetail(this._job.id,this._fieldName,selectedOption.id,this._job.charge,FirstName,ContactID,this._job.preBook);if(this._job.dgDocumentation!==this.checkboxValue){this._job.dgDocumentation=this.checkboxValue;await this._dispatchData.updateJobDetail(this._job.id,"DGDocumentation",this._job.dgDocumentation,this._job.charge,FirstName,ContactID,this._job.preBook)}}cancel(){this._$mdDialog.cancel()}}